function GlassPanel({ children, className = "" }) {
  return <div className={`rounded-[1.7rem] border border-white/90 bg-white/73 shadow-[0_18px_55px_rgba(39,75,120,0.09)] backdrop-blur-2xl ${className}`}>{children}</div>;
}

function StatusBadge({ status }) {
  const styles = {
    active: "bg-emerald-100 text-emerald-700", inactive: "bg-slate-200 text-slate-600",
    paused: "bg-amber-100 text-amber-700", pending: "bg-blue-100 text-blue-700",
    approved: "bg-emerald-100 text-emerald-700", rejected: "bg-rose-100 text-rose-700",
    "changes requested": "bg-amber-100 text-amber-700", "replacement requested": "bg-amber-100 text-amber-700",
    suspended: "bg-slate-800 text-white", accepted: "bg-blue-100 text-blue-700",
    "in progress": "bg-violet-100 text-violet-700", completed: "bg-emerald-100 text-emerald-700",
    expired: "bg-slate-200 text-slate-600", published: "bg-emerald-100 text-emerald-700",
    reported: "bg-rose-100 text-rose-700", "under review": "bg-amber-100 text-amber-700",
    resolved: "bg-emerald-100 text-emerald-700",
  };
  return <span className={`inline-flex rounded-full px-3 py-1 text-xs font-extrabold capitalize ${styles[status] || "bg-slate-100 text-slate-600"}`}>{status}</span>;
}

function PageLead({ title, text, action, onAction, icon: Icon = ArrowRight }) {
  return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-3xl font-black tracking-[-0.04em]">{title}</h2><p className="mt-2 max-w-2xl text-slate-500">{text}</p></div>{action && <button onClick={onAction} className="flex items-center justify-center gap-2 rounded-2xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white"><Icon size={17} />{action}</button>}</div>;
}

function InfoCard({ label, value }) { return <div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold uppercase tracking-wider text-slate-400">{label}</p><p className="mt-2 break-words font-extrabold">{value}</p></div>; }
function Back({ onClick, text }) { return <button onClick={onClick} className="mb-5 inline-flex items-center gap-2 rounded-xl bg-white/70 px-4 py-2 text-sm font-extrabold text-slate-600"><ArrowLeft size={16} />{text}</button>; }
function FilterTabs({ values, value, setValue }) { return <div className="mb-5 flex flex-wrap gap-2">{values.map((item) => <button key={item} onClick={() => setValue(item)} className={`rounded-xl px-4 py-2 text-sm font-extrabold capitalize ${value === item ? "bg-slate-950 text-white" : "bg-white/70 text-slate-500"}`}>{item}</button>)}</div>; }
function Input({ label, defaultValue = "", type = "text", placeholder = "" }) { return <label className="block"><span className="mb-2 block text-sm font-extrabold">{label}</span><input type={type} defaultValue={defaultValue} placeholder={placeholder} className="w-full rounded-2xl border border-white/90 bg-white/75 px-4 py-4 text-sm font-semibold outline-none focus:border-blue-300 focus:ring-4 focus:ring-blue-100" /></label>; }
function Select({ label, options }) { return <label className="block"><span className="mb-2 block text-sm font-extrabold">{label}</span><span className="flex rounded-2xl border border-white/90 bg-white/75 px-4"><select className="w-full appearance-none bg-transparent py-4 text-sm font-semibold outline-none">{options.map((item) => <option key={item}>{item}</option>)}</select><ChevronDown size={16} className="my-auto text-slate-400" /></span></label>; }
function TextArea({ label, placeholder = "", defaultValue = "" }) { return <label className="block"><span className="mb-2 block text-sm font-extrabold">{label}</span><textarea defaultValue={defaultValue} placeholder={placeholder} className="min-h-36 w-full rounded-2xl border border-white/90 bg-white/75 p-4 text-sm font-semibold outline-none focus:border-blue-300 focus:ring-4 focus:ring-blue-100" /></label>; }

export default function AdministratorPage({ screen = "dashboard" }) {
  const navigate = useNavigate();
  const location = useLocation();
  const params = useParams();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notice, setNotice] = useState("");
  const [filter, setFilter] = useState("all");
  const [decision, setDecision] = useState(null);
  const [decisionNote, setDecisionNote] = useState("");
  const [userItems, setUserItems] = useState(users);
  const [categoryItems, setCategoryItems] = useState(categories);

  const recordId = params.id || "PA-301";
  const activeApplication = providerApplications.find((item) => item.id === recordId) || providerApplications[0];
  const activeUser = userItems.find((item) => item.id === recordId) || userItems[0];
  const activeService = services.find((item) => item.id === recordId) || services[0];
  const activeAd = wantedAds.find((item) => item.id === recordId) || wantedAds[0];
  const activeBooking = bookings.find((item) => item.id === recordId) || bookings[0];
  const activeComplaint = complaints.find((item) => item.id === recordId) || complaints[0];

  const showNotice = (message) => { setNotice(message); window.setTimeout(() => setNotice(""), 2800); };
  const go = (path) => { setSidebarOpen(false); navigate(path); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const toggleUserStatus = (id) => setUserItems((current) => current.map((item) => item.id === id ? { ...item, status: item.status === "suspended" ? "active" : "suspended" } : item));
  const toggleCategory = (id) => setCategoryItems((current) => current.map((item) => item.id === id ? { ...item, status: item.status === "active" ? "inactive" : "active" } : item));

  const navItems = [
    [LayoutDashboard, "Dashboard", "/admin/dashboard"],
    [UserRoundCheck, "Provider Applications", "/admin/provider-applications"],
    [Users, "Users", "/admin/users"],
    [FolderCog, "Categories", "/admin/categories"],
    [BriefcaseBusiness, "Services", "/admin/services"],
    [FileText, "Wanted Ads", "/admin/wanted-ads"],
    [CalendarDays, "Bookings", "/admin/bookings"],
    [Star, "Reviews", "/admin/reviews"],
    [MessageSquareText, "Complaints", "/admin/complaints"],
    [CircleDollarSign, "Revenue", "/admin/revenue"], [BarChart3, "Reports", "/admin/reports"],
    [Bell, "Notifications", "/admin/notifications"],
    [Activity, "Audit Logs", "/admin/audit-logs"],
    [Settings, "Settings", "/admin/settings"],
  ];

  return <div className="min-h-screen bg-[#f3f8fc] text-slate-900">
    {/* Decorative background fields preserve visual continuity while using a stronger admin accent. */}
    <div className="pointer-events-none fixed inset-0 overflow-hidden"><div className="absolute -left-36 -top-28 h-[29rem] w-[29rem] rounded-full bg-indigo-300/30 blur-3xl" /><div className="absolute right-[-12rem] top-1/4 h-[32rem] w-[32rem] rounded-full bg-cyan-200/30 blur-3xl" /></div>
    <AnimatePresence>{notice && <motion.div initial={{ opacity: 0, y: -15 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="fixed left-1/2 top-5 z-[100] -translate-x-1/2 rounded-2xl bg-slate-950/90 px-5 py-3 text-sm font-bold text-white shadow-2xl backdrop-blur-xl">{notice}</motion.div>}</AnimatePresence>
    <AnimatePresence>{sidebarOpen && <motion.button initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setSidebarOpen(false)} className="fixed inset-0 z-40 bg-slate-950/40 backdrop-blur-sm lg:hidden" />}</AnimatePresence>

    {/* Administrator sidebar exposes platform-wide oversight and governance pages. */}
    <aside className={`fixed inset-y-0 left-0 z-50 w-[310px] transform border-r border-white/80 bg-white/82 p-4 shadow-2xl backdrop-blur-2xl transition lg:translate-x-0 ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-full flex-col"><div className="flex items-center justify-between px-2 py-2"><button onClick={() => go("/")} className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-gradient-to-br from-indigo-700 to-cyan-500 text-white"><Wrench size={20} /></span><span className="text-xl font-black">Service<span className="text-indigo-600">Link</span></span></button><button onClick={() => setSidebarOpen(false)} className="grid h-9 w-9 place-items-center rounded-xl lg:hidden"><X size={19} /></button></div>
      <div className="my-5 rounded-2xl bg-gradient-to-br from-slate-950 via-indigo-950 to-indigo-700 p-4 text-white shadow-lg"><div className="flex items-center justify-between"><p className="text-xs font-bold text-indigo-100">ADMINISTRATOR</p><ShieldCheck size={19} /></div><p className="mt-1 font-black">Platform Admin</p><p className="mt-1 text-xs text-indigo-100">Full platform oversight</p></div>
      <nav className="flex-1 space-y-1 overflow-y-auto pr-1">{navItems.map(([Icon, label, path]) => { const active = location.pathname === path || (path !== "/admin/dashboard" && location.pathname.startsWith(path)); return <button key={path} onClick={() => go(path)} className={`flex w-full items-center gap-3 rounded-2xl px-4 py-2.5 text-left text-sm font-extrabold transition ${active ? "bg-slate-950 text-white shadow-lg" : "text-slate-600 hover:bg-indigo-50 hover:text-indigo-700"}`}><Icon size={18} />{label}{label === "Provider Applications" && <span className="ml-auto rounded-full bg-blue-600 px-2 py-0.5 text-[10px] text-white">2</span>}{label === "Complaints" && <span className="ml-auto rounded-full bg-amber-500 px-2 py-0.5 text-[10px] text-white">1</span>}</button>; })}</nav>
      <div className="border-t border-slate-200/70 pt-3"><button onClick={() => go("/")} className="flex w-full items-center gap-3 rounded-2xl px-4 py-2.5 text-sm font-extrabold text-slate-600"><ArrowLeft size={18} />Public website</button><button onClick={() => go("/")} className="flex w-full items-center gap-3 rounded-2xl px-4 py-2.5 text-sm font-extrabold text-rose-600"><LogOut size={18} />Log out</button></div></div>
    </aside>

    <div className="relative z-10 lg:pl-[310px]">
      {/* Sticky admin header identifies the current management area and urgent queues. */}
      <header className="sticky top-0 z-30 px-4 pt-4 sm:px-6"><div className="mx-auto flex max-w-7xl items-center justify-between rounded-[1.5rem] border border-white/90 bg-white/74 px-4 py-3 shadow-lg backdrop-blur-2xl"><div className="flex items-center gap-3"><button onClick={() => setSidebarOpen(true)} className="grid h-10 w-10 place-items-center rounded-xl bg-slate-100 lg:hidden"><Menu size={20} /></button><div><p className="text-xs font-bold uppercase tracking-wider text-indigo-600">Administration</p><h1 className="font-black sm:text-lg">{pageTitles[screen]}</h1></div></div><div className="flex items-center gap-2"><button onClick={() => go("/admin/provider-applications")} className="hidden rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-extrabold text-white sm:block">Review queue</button><button onClick={() => go("/admin/notifications")} className="relative grid h-10 w-10 place-items-center rounded-xl bg-white shadow-sm"><Bell size={18} /><span className="absolute right-2 top-2 h-2 w-2 rounded-full bg-rose-500" /></button><button className="grid h-10 w-10 place-items-center rounded-xl bg-slate-950 text-sm font-black text-white">AD</button></div></div></header>

      <main className="mx-auto max-w-7xl px-4 py-8 sm:px-6"><AnimatePresence mode="wait"><motion.div key={`${screen}-${recordId}`} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.2 }}>
        {screen === "dashboard" && <><Dashboard go={go} /><AdminRevenueSummary go={go} /></>}
        {screen === "applications" && <Applications filter={filter} setFilter={setFilter} go={go} />}
        {screen === "application-details" && <ApplicationDetails application={activeApplication} decision={decision} setDecision={setDecision} decisionNote={decisionNote} setDecisionNote={setDecisionNote} showNotice={showNotice} go={go} />}
        {screen === "users" && <UsersPage users={userItems} filter={filter} setFilter={setFilter} toggleStatus={toggleUserStatus} go={go} />}
        {screen === "user-details" && <UserDetails user={activeUser} toggleStatus={toggleUserStatus} showNotice={showNotice} go={go} />}
        {screen === "categories" && <Categories items={categoryItems} toggleCategory={toggleCategory} showNotice={showNotice} go={go} />}
        {screen === "category-form" && <CategoryForm go={go} showNotice={showNotice} editing={Boolean(params.id)} />}
        {screen === "services" && <ServicesPage go={go} showNotice={showNotice} />}
        {screen === "service-details" && <ServiceDetails service={activeService} go={go} showNotice={showNotice} />}
        {screen === "wanted-ads" && <WantedAdsPage go={go} showNotice={showNotice} />}
        {screen === "wanted-ad-details" && <WantedAdDetails ad={activeAd} go={go} showNotice={showNotice} />}
        {screen === "bookings" && <BookingsPage go={go} />}
        {screen === "booking-details" && <BookingDetails booking={activeBooking} go={go} showNotice={showNotice} />}
        {screen === "reviews" && <ReviewsPage showNotice={showNotice} />}
        {screen === "complaints" && <ComplaintsPage go={go} />}
        {screen === "complaint-details" && <ComplaintDetails complaint={activeComplaint} go={go} showNotice={showNotice} />}
        {screen === "revenue" && <Revenue go={go} />}
        {screen === "reports" && <Reports />}
        {screen === "notifications" && <Notifications showNotice={showNotice} />}
        {screen === "audit" && <AuditLogs />}
        {screen === "settings" && <PlatformSettings showNotice={showNotice} />}
      </motion.div></AnimatePresence></main>
    </div>
  </div>;
}

// Dashboard summarizes queues, marketplace activity and issues requiring attention.
function Dashboard({ go }) {
  const metrics = [[UserRoundCheck,"Pending applications","2","bg-blue-100 text-blue-700"],[Users,"Active users","184","bg-indigo-100 text-indigo-700"],[CalendarDays,"Bookings this month","67","bg-emerald-100 text-emerald-700"],[MessageSquareText,"Open complaints","1","bg-amber-100 text-amber-700"]];
  return <div className="space-y-7"><GlassPanel className="overflow-hidden bg-gradient-to-r from-slate-950 via-indigo-950 to-indigo-800 p-7 text-white"><p className="text-sm font-bold text-cyan-300">PLATFORM OVERVIEW</p><h2 className="mt-2 text-3xl font-black">Administrator control centre</h2><p className="mt-3 max-w-2xl text-slate-300">Review provider applications, moderate marketplace records and monitor operational activity.</p><div className="mt-6 flex flex-wrap gap-3"><button onClick={() => go("/admin/provider-applications")} className="rounded-2xl bg-white px-5 py-3 text-sm font-extrabold text-indigo-700">Review applications</button><button onClick={() => go("/admin/complaints")} className="rounded-2xl border border-white/20 bg-white/10 px-5 py-3 text-sm font-extrabold">Open complaints</button></div></GlassPanel><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(([Icon,label,value,colour]) => <GlassPanel key={label} className="p-5"><span className={`grid h-11 w-11 place-items-center rounded-2xl ${colour}`}><Icon size={20} /></span><p className="mt-5 text-3xl font-black">{value}</p><p className="mt-1 text-sm font-semibold text-slate-500">{label}</p></GlassPanel>)}</div><div className="grid gap-6 xl:grid-cols-2"><GlassPanel className="p-6"><PageLead title="Application queue" text="Applications requiring administrator attention." />{providerApplications.slice(0,2).map((item) => <button key={item.id} onClick={() => go(`/admin/provider-applications/${item.id}`)} className="mb-3 flex w-full items-center gap-3 rounded-2xl bg-slate-50 p-4 text-left hover:bg-indigo-50"><span className="grid h-11 w-11 place-items-center rounded-xl bg-indigo-100 text-indigo-700"><UserRoundCheck size={18} /></span><span className="flex-1"><span className="block font-extrabold">{item.provider}</span><span className="text-sm text-slate-500">{item.id} · {item.submitted}</span></span><StatusBadge status={item.status} /><ChevronRight size={18} /></button>)}</GlassPanel><GlassPanel className="p-6"><PageLead title="Recent administration" text="Latest sensitive changes recorded in the audit trail." />{auditLogs.slice(0,3).map((log) => <div key={log.id} className="mb-3 flex gap-3 rounded-2xl bg-slate-50 p-4"><Activity size={18} className="mt-0.5 text-indigo-600" /><div><p className="font-extrabold">{log.action}</p><p className="mt-1 text-sm text-slate-500">{log.target} · {log.time}</p></div></div>)}</GlassPanel></div></div>;
}

function Applications({ filter, setFilter, go }) { const items = filter === "all" ? providerApplications : providerApplications.filter((item) => item.status === filter); return <div><PageLead title="Provider Applications" text="Review provider profiles and supporting evidence before enabling marketplace access." /><FilterTabs values={["all","pending","changes requested","approved"]} value={filter} setValue={setFilter} /><div className="space-y-4">{items.map((item) => <GlassPanel key={item.id} className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-indigo-100 text-indigo-700"><UserRoundCheck size={23} /></span><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-lg font-black">{item.provider}</h3><StatusBadge status={item.status} /></div><p className="mt-1 text-sm text-slate-500">{item.id} · {item.owner} · Submitted {item.submitted}</p><p className="mt-3 text-sm font-semibold">{item.categories} · {item.documents} documents</p></div><button onClick={() => go(`/admin/provider-applications/${item.id}`)} className="rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white">Review application</button></div></GlassPanel>)}</div></div>; }

function ApplicationDetails({ application, decision, setDecision, decisionNote, setDecisionNote, showNotice, go }) { const docs = qualifications.filter((q) => q.applicationId === application.id); return <div><Back onClick={() => go("/admin/provider-applications")} text="Back to applications" /><GlassPanel className="p-6 sm:p-8"><div className="flex flex-col justify-between gap-4 sm:flex-row"><div><p className="text-sm font-bold text-indigo-600">{application.id}</p><h2 className="mt-2 text-3xl font-black">{application.provider}</h2><p className="mt-2 text-slate-500">Applicant: {application.owner} · Submitted {application.submitted}</p></div><StatusBadge status={application.status} /></div><div className="mt-7 grid gap-4 sm:grid-cols-3"><InfoCard label="Categories" value={application.categories} /><InfoCard label="Documents" value={String(application.documents)} /><InfoCard label="Current status" value={application.status} /></div><div className="mt-7 rounded-2xl bg-slate-50 p-5"><h3 className="font-black">Professional summary</h3><p className="mt-2 leading-7 text-slate-600">Independent local provider applying to publish electrical and household maintenance services.</p></div><h3 className="mt-7 text-xl font-black">Qualification evidence</h3><div className="mt-4 space-y-3">{(docs.length ? docs : qualifications.slice(0,2)).map((doc) => <div key={doc.id} className="flex flex-col gap-3 rounded-2xl bg-slate-50 p-4 sm:flex-row sm:items-center"><FileText size={20} className="text-indigo-600" /><div className="flex-1"><p className="font-extrabold">{doc.title}</p><p className="mt-1 text-sm text-slate-500">{doc.issuer} · {doc.file}</p></div><StatusBadge status={doc.status} /><button onClick={() => showNotice(`Protected preview opened for ${doc.file}`)} className="rounded-xl bg-white px-4 py-2 text-sm font-extrabold">Preview</button></div>)}</div><div className="mt-7 grid gap-3 sm:grid-cols-3"><button onClick={() => setDecision("approve")} className="rounded-2xl bg-emerald-600 px-5 py-4 text-sm font-extrabold text-white">Approve</button><button onClick={() => setDecision("changes requested")} className="rounded-2xl bg-amber-100 px-5 py-4 text-sm font-extrabold text-amber-800">Request changes</button><button onClick={() => setDecision("reject")} className="rounded-2xl bg-rose-100 px-5 py-4 text-sm font-extrabold text-rose-700">Reject</button></div></GlassPanel><AnimatePresence>{decision && <DecisionModal decision={decision} note={decisionNote} setNote={setDecisionNote} close={() => setDecision(null)} confirm={() => { showNotice(`Application decision recorded: ${decision}`); setDecision(null); }} />}</AnimatePresence></div>; }

function DecisionModal({ decision, note, setNote, close, confirm }) { return <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="fixed inset-0 z-[90] grid place-items-center bg-slate-950/45 p-4 backdrop-blur-sm"><GlassPanel className="w-full max-w-lg p-6"><h3 className="text-2xl font-black capitalize">{decision} application</h3><p className="mt-2 text-sm text-slate-500">A reason is required for changes or rejection and will be visible to the provider.</p><textarea value={note} onChange={(e) => setNote(e.target.value)} className="mt-5 min-h-32 w-full rounded-2xl border border-slate-200 p-4 outline-none" placeholder="Write a clear administrator decision note" /><div className="mt-4 flex gap-3"><button onClick={close} className="flex-1 rounded-xl bg-slate-100 py-3 font-extrabold">Cancel</button><button onClick={confirm} className="flex-1 rounded-xl bg-indigo-700 py-3 font-extrabold text-white">Confirm decision</button></div></GlassPanel></motion.div>; }

function UsersPage({ users, filter, setFilter, toggleStatus, go }) { const items = filter === "all" ? users : users.filter((u) => u.role === filter || u.status === filter); return <div><PageLead title="User Management" text="Inspect accounts, roles and access status. Sensitive changes should be audit logged." /><FilterTabs values={["all","customer","provider","suspended"]} value={filter} setValue={setFilter} /><GlassPanel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-slate-950 text-white"><tr>{["User","Role","Joined","Status","Actions"].map((h) => <th key={h} className="px-5 py-4">{h}</th>)}</tr></thead><tbody>{items.map((user) => <tr key={user.id} className="border-b border-slate-100"><td className="px-5 py-4"><p className="font-extrabold">{user.name}</p><p className="mt-1 text-xs text-slate-500">{user.email} · {user.id}</p></td><td className="px-5 py-4 capitalize">{user.role}</td><td className="px-5 py-4">{user.joined}</td><td className="px-5 py-4"><StatusBadge status={user.status} /></td><td className="px-5 py-4"><div className="flex gap-2"><button onClick={() => go(`/admin/users/${user.id}`)} className="rounded-xl bg-slate-950 px-3 py-2 text-xs font-extrabold text-white">View</button><button onClick={() => toggleStatus(user.id)} className="rounded-xl bg-amber-50 px-3 py-2 text-xs font-extrabold text-amber-700">{user.status === "suspended" ? "Restore" : "Suspend"}</button></div></td></tr>)}</tbody></table></div></GlassPanel></div>; }
function UserDetails({ user, toggleStatus, showNotice, go }) { return <div><Back onClick={() => go("/admin/users")} text="Back to users" /><GlassPanel className="p-6 sm:p-8"><div className="flex flex-col justify-between gap-4 sm:flex-row"><div><p className="text-sm font-bold text-indigo-600">{user.id}</p><h2 className="mt-2 text-3xl font-black">{user.name}</h2><p className="mt-2 text-slate-500">{user.email}</p></div><StatusBadge status={user.status} /></div><div className="mt-7 grid gap-4 sm:grid-cols-4"><InfoCard label="Role" value={user.role} /><InfoCard label="Joined" value={user.joined} /><InfoCard label="Status" value={user.status} /><InfoCard label="Recent activity" value="Today" /></div><div className="mt-7 flex flex-wrap gap-3"><button onClick={() => { toggleStatus(user.id); showNotice("User access status updated in the prototype"); }} className="rounded-xl bg-amber-100 px-5 py-3 text-sm font-extrabold text-amber-800">{user.status === "suspended" ? "Restore account" : "Suspend account"}</button><button onClick={() => showNotice("Password reset notification would be sent here")} className="rounded-xl bg-blue-100 px-5 py-3 text-sm font-extrabold text-blue-700">Send password reset</button><button onClick={() => showNotice("User activity report prepared") } className="rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white">View activity</button></div></GlassPanel></div>; }

function Categories({ items, toggleCategory, showNotice, go }) { return <div><PageLead title="Category Management" text="Maintain the controlled service taxonomy used by listings and wanted advertisements." action="Add category" onAction={() => go("/admin/categories/create")} /><div className="grid gap-5 xl:grid-cols-2">{items.map((item) => <GlassPanel key={item.id} className="p-5"><div className="flex items-start justify-between"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-indigo-100 text-indigo-700"><FolderCog size={21} /></span><StatusBadge status={item.status} /></div><h3 className="mt-5 text-xl font-black">{item.name}</h3><p className="mt-1 text-sm text-slate-500">{item.id} · {item.services} services · {item.providers} providers</p><div className="mt-5 flex gap-2"><button onClick={() => go(`/admin/categories/${item.id}/edit`)} className="flex-1 rounded-xl bg-slate-950 px-4 py-3 text-sm font-extrabold text-white">Edit</button><button onClick={() => toggleCategory(item.id)} className="flex-1 rounded-xl bg-indigo-50 px-4 py-3 text-sm font-extrabold text-indigo-700">{item.status === "active" ? "Deactivate" : "Activate"}</button><button onClick={() => showNotice("Categories with linked records cannot be deleted") } className="grid h-11 w-11 place-items-center rounded-xl bg-rose-50 text-rose-600"><Trash2 size={18} /></button></div></GlassPanel>)}</div></div>; }
function CategoryForm({ go, showNotice, editing }) { return <GlassPanel className="p-6 sm:p-8"><Back onClick={() => go("/admin/categories")} text="Back to categories" /><PageLead title={editing ? "Edit Category" : "Add Category"} text="Create clear categories without duplicating existing marketplace classifications." /><form onSubmit={(e) => { e.preventDefault(); showNotice(editing ? "Category updated" : "Category created"); go("/admin/categories"); }} className="grid gap-5"><Input label="Category name" defaultValue={editing ? "Electrical" : ""} placeholder="Enter category name" /><TextArea label="Description" defaultValue={editing ? "Electrical installation, inspection and repair services." : ""} placeholder="Explain the services that belong in this category" /><Select label="Initial status" options={["Active","Inactive"]} /><div className="flex justify-end gap-3"><button type="button" onClick={() => go("/admin/categories")} className="rounded-xl bg-slate-100 px-5 py-3 font-extrabold">Cancel</button><button className="rounded-xl bg-indigo-700 px-5 py-3 font-extrabold text-white">Save category</button></div></form></GlassPanel>; }

function ServicesPage({ go, showNotice }) { return <div><PageLead title="Service Moderation" text="Inspect listings, reported content, status and provider ownership." /><div className="space-y-4">{services.map((item) => <GlassPanel key={item.id} className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center"><span className="grid h-13 w-13 place-items-center rounded-2xl bg-blue-100 text-blue-700"><BriefcaseBusiness size={21} /></span><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-lg font-black">{item.title}</h3><StatusBadge status={item.status} />{item.reports > 0 && <span className="rounded-full bg-rose-100 px-3 py-1 text-xs font-extrabold text-rose-700">{item.reports} report</span>}</div><p className="mt-1 text-sm text-slate-500">{item.id} · {item.provider} · {item.category}</p><p className="mt-2 text-sm font-semibold">{item.price}</p></div><button onClick={() => go(`/admin/services/${item.id}`)} className="rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white">Inspect service</button></div></GlassPanel>)}</div></div>; }
function ServiceDetails({ service, go, showNotice }) { return <div><Back onClick={() => go("/admin/services")} text="Back to services" /><GlassPanel className="p-6 sm:p-8"><div className="flex justify-between gap-4"><div><p className="text-sm font-bold text-indigo-600">{service.id} · {service.category}</p><h2 className="mt-2 text-3xl font-black">{service.title}</h2><p className="mt-2 text-slate-500">Published by {service.provider}</p></div><StatusBadge status={service.status} /></div><div className="mt-7 grid gap-4 sm:grid-cols-3"><InfoCard label="Price" value={service.price} /><InfoCard label="Reports" value={String(service.reports)} /><InfoCard label="Provider" value={service.provider} /></div><p className="mt-6 rounded-2xl bg-slate-50 p-5 leading-7 text-slate-600">Inspection and repair of common household faults. The complete listing description and moderation history appear here.</p><div className="mt-6 flex flex-wrap gap-3"><button onClick={() => showNotice("Service status updated") } className="rounded-xl bg-amber-100 px-5 py-3 text-sm font-extrabold text-amber-800">Pause listing</button><button onClick={() => showNotice("Provider warning recorded") } className="rounded-xl bg-blue-100 px-5 py-3 text-sm font-extrabold text-blue-700">Warn provider</button><button onClick={() => showNotice("Removal confirmation will open here") } className="rounded-xl bg-rose-100 px-5 py-3 text-sm font-extrabold text-rose-700">Remove listing</button></div></GlassPanel></div>; }

function WantedAdsPage({ go, showNotice }) { return <div><PageLead title="Wanted Ad Moderation" text="Inspect customer requests, report counts and offer activity." /><div className="space-y-4">{wantedAds.map((item) => <GlassPanel key={item.id} className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center"><span className="grid h-13 w-13 place-items-center rounded-2xl bg-violet-100 text-violet-700"><FileText size={21} /></span><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-lg font-black">{item.title}</h3><StatusBadge status={item.status} />{item.reports > 0 && <span className="rounded-full bg-rose-100 px-3 py-1 text-xs font-extrabold text-rose-700">Reported</span>}</div><p className="mt-1 text-sm text-slate-500">{item.id} · {item.customer} · {item.category} · {item.offers} offers</p></div><button onClick={() => go(`/admin/wanted-ads/${item.id}`)} className="rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white">Inspect ad</button></div></GlassPanel>)}</div></div>; }
function WantedAdDetails({ ad, go, showNotice }) { return <div><Back onClick={() => go("/admin/wanted-ads")} text="Back to wanted ads" /><GlassPanel className="p-6 sm:p-8"><div className="flex justify-between gap-4"><div><p className="text-sm font-bold text-indigo-600">{ad.id} · {ad.category}</p><h2 className="mt-2 text-3xl font-black">{ad.title}</h2><p className="mt-2 text-slate-500">Published by {ad.customer}</p></div><StatusBadge status={ad.status} /></div><div className="mt-7 grid gap-4 sm:grid-cols-3"><InfoCard label="Offer deadline" value={ad.deadline} /><InfoCard label="Offers" value={String(ad.offers)} /><InfoCard label="Reports" value={String(ad.reports)} /></div><p className="mt-6 rounded-2xl bg-slate-50 p-5 leading-7 text-slate-600">The customer description is shown here for moderation. Private address and contact details remain access controlled and should only be viewed when operationally necessary.</p><div className="mt-6 flex gap-3"><button onClick={() => showNotice("Wanted ad hidden from public discovery") } className="rounded-xl bg-amber-100 px-5 py-3 text-sm font-extrabold text-amber-800">Hide ad</button><button onClick={() => showNotice("Wanted ad removal confirmation will open") } className="rounded-xl bg-rose-100 px-5 py-3 text-sm font-extrabold text-rose-700">Remove ad</button></div></GlassPanel></div>; }

function BookingsPage({ go }) { return <div><PageLead title="Booking Oversight" text="Inspect booking state, source and involved accounts without altering normal workflow unnecessarily." /><div className="space-y-4">{bookings.map((item) => <GlassPanel key={item.id} className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center"><span className="grid h-13 w-13 place-items-center rounded-2xl bg-emerald-100 text-emerald-700"><CalendarDays size={21} /></span><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-lg font-black">{item.title}</h3><StatusBadge status={item.status} /></div><p className="mt-1 text-sm text-slate-500">{item.id} · {item.customer} and {item.provider}</p><p className="mt-2 text-sm font-semibold">{item.date} · {item.value} · {item.source}</p></div><button onClick={() => go(`/admin/bookings/${item.id}`)} className="rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white">View booking</button></div></GlassPanel>)}</div></div>; }
function BookingDetails({ booking, go, showNotice }) { return <div><Back onClick={() => go("/admin/bookings")} text="Back to bookings" /><GlassPanel className="p-6 sm:p-8"><div className="flex justify-between gap-4"><div><p className="text-sm font-bold text-indigo-600">{booking.id}</p><h2 className="mt-2 text-3xl font-black">{booking.title}</h2><p className="mt-2 text-slate-500">{booking.customer} and {booking.provider}</p></div><StatusBadge status={booking.status} /></div><div className="mt-7 grid gap-4 sm:grid-cols-4"><InfoCard label="Date" value={booking.date} /><InfoCard label="Value" value={booking.value} /><InfoCard label="Source" value={booking.source} /><InfoCard label="Current state" value={booking.status} /></div><div className="mt-6 rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><p className="text-xs font-bold uppercase text-emerald-700">Financial breakdown</p><div className="mt-4 grid gap-3 sm:grid-cols-4"><InfoCard label="Gross value" value={booking.value}/><InfoCard label="Commission rate" value="10%"/><InfoCard label="Commission" value={booking.id === "BK-1026" ? "LKR 450" : booking.id === "BK-1038" ? "LKR 380" : "LKR 350"}/><InfoCard label="Provider net" value={booking.id === "BK-1026" ? "LKR 4,050" : booking.id === "BK-1038" ? "LKR 3,420" : "LKR 3,150"}/></div><p className="mt-4 text-xs text-emerald-800">Financial status: {booking.status === "completed" ? "Recorded" : "Pending"}. Customer pays provider directly.</p></div><div className="mt-6 rounded-2xl border border-blue-200 bg-blue-50 p-5 text-sm leading-6 text-blue-900"><ShieldCheck size={20} className="mb-2 text-blue-600" />Administrator actions should preserve booking history. Corrections and exceptional changes must create audit records.</div><button onClick={() => showNotice("Complete booking history opened") } className="mt-6 rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white">View full history</button></GlassPanel></div>; }

function ReviewsPage({ showNotice }) { return <div><PageLead title="Review Moderation" text="Inspect reported or inappropriate reviews while preserving verified customer feedback." /><div className="grid gap-5 xl:grid-cols-2">{reviews.map((item) => <GlassPanel key={item.id} className="p-5"><div className="flex justify-between gap-3"><div><h3 className="font-black">{item.customer} reviewed {item.provider}</h3><p className="mt-1 text-sm text-slate-500">{item.id} · Booking {item.booking}</p></div><StatusBadge status={item.status} /></div><div className="mt-3 flex text-amber-500">{[1,2,3,4,5].map((n) => <Star key={n} size={16} className={n <= item.rating ? "fill-current" : "text-slate-200"} />)}</div><p className="mt-4 leading-7 text-slate-600">{item.text}</p><div className="mt-5 flex gap-2"><button onClick={() => showNotice("Review retained") } className="flex-1 rounded-xl bg-emerald-50 px-4 py-3 text-sm font-extrabold text-emerald-700">Keep published</button><button onClick={() => showNotice("Review hidden pending investigation") } className="flex-1 rounded-xl bg-rose-50 px-4 py-3 text-sm font-extrabold text-rose-700">Hide review</button></div></GlassPanel>)}</div></div>; }

function ComplaintsPage({ go }) { return <div><PageLead title="Complaint Management" text="Investigate booking-linked disputes and record fair, traceable outcomes." /><div className="space-y-4">{complaints.map((item) => <GlassPanel key={item.id} className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center"><span className="grid h-13 w-13 place-items-center rounded-2xl bg-amber-100 text-amber-700"><AlertCircle size={21} /></span><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-lg font-black">{item.subject}</h3><StatusBadge status={item.status} /></div><p className="mt-1 text-sm text-slate-500">{item.id} · {item.complainant} against {item.against}</p><p className="mt-2 text-sm font-semibold">Record {item.record} · Opened {item.opened}</p></div><button onClick={() => go(`/admin/complaints/${item.id}`)} className="rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white">Manage complaint</button></div></GlassPanel>)}</div></div>; }
function ComplaintDetails({ complaint, go, showNotice }) { return <div><Back onClick={() => go("/admin/complaints")} text="Back to complaints" /><GlassPanel className="p-6 sm:p-8"><div className="flex justify-between gap-4"><div><p className="text-sm font-bold text-indigo-600">{complaint.id} · {complaint.record}</p><h2 className="mt-2 text-3xl font-black">{complaint.subject}</h2><p className="mt-2 text-slate-500">{complaint.complainant} against {complaint.against}</p></div><StatusBadge status={complaint.status} /></div><div className="mt-6 grid gap-5 xl:grid-cols-2"><div className="rounded-2xl bg-slate-50 p-5"><p className="text-xs font-bold uppercase text-slate-400">Customer statement</p><p className="mt-2 leading-7 text-slate-600">The customer disputes an additional charge that was not understood before the service was completed.</p></div><div className="rounded-2xl bg-slate-50 p-5"><p className="text-xs font-bold uppercase text-slate-400">Provider response</p><p className="mt-2 leading-7 text-slate-600">The provider states that an additional replacement part was approved verbally during the visit.</p></div></div><div className="mt-6"><TextArea label="Administrator resolution note" placeholder="Record evidence considered, decision and required follow-up" /></div><div className="mt-5 flex flex-wrap gap-3"><button onClick={() => showNotice("Additional evidence requested") } className="rounded-xl bg-blue-100 px-5 py-3 text-sm font-extrabold text-blue-700">Request evidence</button><button onClick={() => showNotice("Complaint marked resolved") } className="rounded-xl bg-emerald-600 px-5 py-3 text-sm font-extrabold text-white">Resolve complaint</button><button onClick={() => showNotice("Account action review opened") } className="rounded-xl bg-rose-100 px-5 py-3 text-sm font-extrabold text-rose-700">Consider account action</button></div></GlassPanel></div>; }

function AdminRevenueSummary({ go }) { return <GlassPanel className="mt-7 p-6"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-center"><div><p className="text-sm font-bold text-emerald-600">COMMISSION REVENUE</p><h3 className="mt-2 text-2xl font-black">LKR 96,400 this month</h3><p className="mt-2 text-sm text-slate-500">From LKR 964,000 completed booking value. LKR 14,200 is pending.</p></div><button onClick={()=>go("/admin/revenue")} className="rounded-xl bg-emerald-600 px-5 py-3 text-sm font-extrabold text-white">View revenue</button></div></GlassPanel>; }
function Revenue({ go }) { const records=[{id:"TR-401",booking:"BK-1026",provider:"Kalana HomeTech",source:"Direct booking",gross:"LKR 4,500",fee:"LKR 450",net:"LKR 4,050",status:"recorded"},{id:"TR-402",booking:"BK-1038",provider:"Kalana HomeTech",source:"Accepted offer",gross:"LKR 3,800",fee:"LKR 380",net:"LKR 3,420",status:"pending"},{id:"TR-403",booking:"BK-1042",provider:"LankaFix Electrical",source:"Direct booking",gross:"LKR 3,500",fee:"LKR 350",net:"LKR 3,150",status:"pending"}]; const bars=[48,62,55,73,88,79]; return <div><PageLead title="Revenue and Commission" text="Review simulated commission records. Customers pay providers directly; ServiceLink records a 10% provider-side commission after completion." action="Commission settings" onAction={()=>go("/admin/settings")} icon={Settings}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[[CircleDollarSign,"Completed booking value","LKR 964,000"],[TrendingUp,"Commission revenue","LKR 96,400"],[Clock3,"Pending commission","LKR 14,200"],[Users,"Provider net value","LKR 867,600"]].map(([Icon,label,value])=><GlassPanel key={label} className="p-5"><Icon size={22} className="text-emerald-600"/><p className="mt-5 text-2xl font-black">{value}</p><p className="mt-1 text-sm font-semibold text-slate-500">{label}</p></GlassPanel>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><GlassPanel className="p-6"><h3 className="text-xl font-black">Monthly commission trend</h3><div className="mt-8 flex h-52 items-end gap-4">{bars.map((h,i)=><div key={i} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-xl bg-gradient-to-t from-emerald-700 to-cyan-400" style={{height:`${h}%`}}/><span className="text-xs font-bold text-slate-400">{["Apr","May","Jun","Jul","Aug","Sep"][i]}</span></div>)}</div></GlassPanel><GlassPanel className="p-6"><h3 className="text-xl font-black">Revenue source</h3><div className="mt-6 space-y-5">{[["Direct bookings","68%","bg-blue-600"],["Accepted offers","32%","bg-violet-600"],["Electrical category","44%","bg-emerald-600"]].map(([label,value,colour])=><div key={label}><div className="flex justify-between text-sm font-bold"><span>{label}</span><span>{value}</span></div><div className="mt-2 h-2 rounded-full bg-slate-100"><div className={`h-full rounded-full ${colour}`} style={{width:value}}/></div></div>)}</div></GlassPanel></div><GlassPanel className="mt-6 overflow-hidden"><div className="border-b border-slate-100 p-5"><h3 className="text-xl font-black">Commission transactions</h3><p className="mt-1 text-sm text-slate-500">Demonstration records until MySQL and completion workflows are connected.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-950 text-white"><tr>{["Transaction","Booking","Provider","Source","Gross","Commission","Provider net","Status"].map(h=><th key={h} className="px-4 py-4">{h}</th>)}</tr></thead><tbody>{records.map(r=><tr key={r.id} className="border-b border-slate-100"><td className="px-4 py-4 font-extrabold">{r.id}</td><td className="px-4 py-4"><button onClick={()=>go(`/admin/bookings/${r.booking}`)} className="font-extrabold text-indigo-700">{r.booking}</button></td><td className="px-4 py-4">{r.provider}</td><td className="px-4 py-4">{r.source}</td><td className="px-4 py-4 font-bold">{r.gross}</td><td className="px-4 py-4 font-black text-emerald-700">{r.fee}</td><td className="px-4 py-4">{r.net}</td><td className="px-4 py-4"><StatusBadge status={r.status}/></td></tr>)}</tbody></table></div></GlassPanel></div>; }
function Reports() { const bars=[42,55,61,50,78,67]; return <div><PageLead title="Reports and Analytics" text="Review aggregate platform activity without exposing unnecessary personal data." action="Export summary" onAction={() => {}} icon={Download} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[[Users,"Registered users","184"],[BadgeCheck,"Approved providers","49"],[CalendarDays,"Completed bookings","312"],[CircleDollarSign,"Estimated booking value","LKR 1.8M"]].map(([Icon,label,value]) => <GlassPanel key={label} className="p-5"><Icon size={22} className="text-indigo-600" /><p className="mt-5 text-3xl font-black">{value}</p><p className="mt-1 text-sm font-semibold text-slate-500">{label}</p></GlassPanel>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_0.7fr]"><GlassPanel className="p-6"><h3 className="text-xl font-black">Monthly bookings</h3><div className="mt-8 flex h-56 items-end gap-4">{bars.map((height,i) => <div key={i} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-xl bg-gradient-to-t from-indigo-700 to-cyan-400" style={{height:`${height}%`}} /><span className="text-xs font-bold text-slate-400">{["Apr","May","Jun","Jul","Aug","Sep"][i]}</span></div>)}</div></GlassPanel><GlassPanel className="p-6"><h3 className="text-xl font-black">Category activity</h3><div className="mt-5 space-y-4">{categories.slice(0,4).map((item) => <div key={item.id}><div className="flex justify-between text-sm font-bold"><span>{item.name}</span><span>{item.services}</span></div><div className="mt-2 h-2 rounded-full bg-slate-100"><div className="h-full rounded-full bg-indigo-600" style={{width:`${Math.min(item.services*2,100)}%`}} /></div></div>)}</div></GlassPanel></div></div>; }
function Notifications({ showNotice }) { const items=["Provider application submitted","Complaint evidence received","Service listing reported","Qualification replacement uploaded"]; return <div><PageLead title="Administrator Notifications" text="High-priority verification, moderation and complaint events appear here." action="Mark all read" onAction={() => showNotice("All administrator notifications marked read")} />{items.map((item,i) => <GlassPanel key={item} className={`mb-3 p-5 ${i < 2 ? "ring-2 ring-indigo-200" : ""}`}><div className="flex gap-4"><span className={`mt-1 h-2.5 w-2.5 rounded-full ${i < 2 ? "bg-indigo-600" : "bg-slate-300"}`} /><div><h3 className="font-black">{item}</h3><p className="mt-1 text-sm text-slate-500">Administrator attention may be required. Open the relevant management queue for details.</p><p className="mt-2 text-xs font-bold text-slate-400">{i + 1} hour(s) ago</p></div></div></GlassPanel>)}</div>; }
function AuditLogs() { return <div><PageLead title="Audit Logs" text="Trace sensitive administrator actions, actors, targets and timestamps." /><GlassPanel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-slate-950 text-white"><tr>{["Log","Actor","Action","Target","Timestamp","IP"].map((h) => <th key={h} className="px-5 py-4">{h}</th>)}</tr></thead><tbody>{auditLogs.map((log) => <tr key={log.id} className="border-b border-slate-100"><td className="px-5 py-4 font-extrabold">{log.id}</td><td className="px-5 py-4">{log.actor}</td><td className="px-5 py-4">{log.action}</td><td className="px-5 py-4 font-bold text-indigo-700">{log.target}</td><td className="px-5 py-4">{log.time}</td><td className="px-5 py-4">{log.ip}</td></tr>)}</tbody></table></div></GlassPanel></div>; }
function PlatformSettings({ showNotice }) { return <GlassPanel className="p-6 sm:p-8"><PageLead title="Platform Settings" text="Manage limited administrative configuration. Critical security settings remain environment controlled." /><form onSubmit={(e) => {e.preventDefault(); showNotice("Platform settings saved in the prototype");}} className="grid gap-5 sm:grid-cols-2"><Input label="Platform name" defaultValue="ServiceLink" /><Input label="Support email" type="email" defaultValue="support@servicelink.test" /><Input label="Maximum qualification file size (MB)" type="number" defaultValue="5" /><Input label="Provider review target (days)" type="number" defaultValue="5" /><Select label="New provider registration" options={["Enabled","Disabled"]} /><Select label="Wanted ad publishing" options={["Enabled","Disabled"]} /><div className="sm:col-span-2 rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><div className="flex items-center gap-3"><CircleDollarSign size={21} className="text-emerald-700"/><div><h3 className="font-black text-emerald-950">Marketplace commission</h3><p className="mt-1 text-sm text-emerald-800">Provider-side commission recorded after completed bookings.</p></div></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><Select label="Commission status" options={["Enabled","Disabled"]}/><Input label="Default commission rate (%)" type="number" defaultValue="10"/></div><p className="mt-4 text-xs leading-5 text-emerald-800">New rates apply only to future bookings. Existing bookings keep their recorded rate. Rate changes should create audit logs.</p></div><div className="sm:col-span-2 rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm leading-6 text-amber-900"><LockKeyhole size={20} className="mb-2 text-amber-700" />Mail credentials, database configuration, encryption keys and session settings must not be editable from this UI.</div><div className="sm:col-span-2 flex justify-end"><button className="rounded-xl bg-indigo-700 px-6 py-3 font-extrabold text-white">Save settings</button></div></form></GlassPanel>; }
